"""Publish implementation outcomes without regrading frozen expectations."""
from __future__ import annotations
from collections import Counter
import json
from pathlib import Path

def collect(path):
    path = Path(path)
    scores = json.loads((path / 'progress.json').read_text())
    receipts = []
    for score in scores:
        receipt = path / score['id'] / 'receipt.json'
        if receipt.exists():
            receipts.append(json.loads(receipt.read_text()))
    jobs = [j for r in receipts for j in r['jobs']]
    errors = [s for s in scores if 'harness_error' in s]
    receipt_posts = sum((len(calls) for r in receipts for calls in r.get('provider_calls_after_cleanup', r['provider_calls']).values()))
    error_posts = sum((len(calls) for s in errors for calls in s.get('provider_calls', {}).values()))
    posts = receipt_posts + error_posts
    workflows = [r for r in receipts if r['workflow'] is not None]
    stable = all((all((value == r['source_after'].get(key) for key, value in r['source_before'].items())) for r in receipts))
    source_hashes = {key: sorted({r['source_after'][key]['sha256'] for r in receipts if key in r['source_after']}) for key in ('hanni.compute.scheduler', 'hanni.compute.registry', 'hanni.compute.transport', 'hanni.workflows.service')}
    return {'cases': len(scores), 'strict_pass': sum((s['passed'] for s in scores)), 'strict_nonpass': sum((not s['passed'] for s in scores)), 'harness_errors': sum(('harness_error' in s for s in scores)), 'receipts': len(receipts), 'by_category': {category: {'cases': sum((s['category'] == category for s in scores)), 'strict_pass': sum((s['category'] == category and s['passed'] for s in scores))} for category in sorted({s['category'] for s in scores})}, 'failing_case_ids': [s['id'] for s in scores if not s['passed']], 'controlled_provider_http_posts': posts, 'receipt_http_posts': receipt_posts, 'harness_error_http_posts': error_posts, 'harness_errors_with_dispatch_diagnostics': sum(('provider_calls' in s for s in errors)), 'real_cluster_model_responses': 0, 'completed_protocol_deliveries': sum((len(r['results']) for r in receipts)), 'job_state_counts': dict(Counter((j['state'] for j in jobs))), 'workflow_controls': {'cases': len(workflows), 'completed': sum((r['workflow']['status'] == 'completed' for r in workflows)), 'partially_completed': sum((r['workflow']['status'] == 'partially_completed' for r in workflows)), 'blocked': sum((r['workflow']['status'] == 'blocked' for r in workflows)), 'artifact_write_entries': sum((r['writes'] for r in workflows))}, 'maximum_observed_controlled_http_overlap': max([r['maximum_overlap'] for r in receipts] + [s['maximum_overlap'] for s in errors if 'maximum_overlap' in s], default=None), 'observed_cleanup_leaks': sum((bool(sum(r['active_reservations'].values()) or r['waiting_tickets'] or r['inflight_count'] or (not r['owned_provider_closed']) or (not r['owned_scheduler_closed']) or r.get('active_provider_handlers_after_cleanup', 0)) for r in receipts)), 'harness_error_observed_cleanup_leaks': sum((bool(not s.get('owned_providers_closed', True) or any((s.get('cleanup_state') or {}).get('active', {}).values()) or (s.get('cleanup_state') or {}).get('waiting', 0) or (s.get('cleanup_state') or {}).get('inflight', 0) or ((s.get('cleanup_state') or {}).get('closed') is False)) for s in errors)), 'harness_errors_without_cleanup_diagnostics': sum(('cleanup_state' not in s for s in errors)), 'dependency_bytes_stable_during_cases': stable if receipts else None, 'source_hashes': source_hashes, 'model_accuracy': None, 'live_model_latency': None, 'live_context_capacity': None}

def publish(baseline, candidate, supplement, output):
    old, new, extra = (collect(baseline), collect(candidate), collect(supplement))
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    rows = ['# Campaign 6 scheduling review', '', 'Scheduling controls use the original ComputeRegistry, ComputeScheduler, InferenceTransport and WorkflowService with isolated SQLite stores and disposable loopback HTTP providers. Controlled replies, context proof fixtures and resource observations are implementation inputs; they are not live model, GPU or cluster evidence.', '', 'The frozen primary corpus contains 79 cases: six in each of the eleven requested categories, plus thirteen cancellation, authority, restart and Strata protocol controls. Inputs and expectations were sealed separately before outputs. Ten separately sealed supplemental cases clarify budgets, background-first reservation and partial-workflow status; they do not change the original 79 expectations.', '', '| Cohort | Cases | Strict pass | Nonpass | Harness errors |', '| --- | ---: | ---: | ---: | ---: |', f"| Archived original, same final harness | {old['cases']} | {old['strict_pass']} | {old['strict_nonpass']} | {old['harness_errors']} |", f"| Candidate, same final harness | {new['cases']} | {new['strict_pass']} | {new['strict_nonpass']} | {new['harness_errors']} |", f"| Separate adequate-budget/status controls | {extra['cases']} | {extra['strict_pass']} | {extra['strict_nonpass']} | {extra['harness_errors']} |", '', 'The first archived-original run scored 67/79. It remains unchanged under baseline-cycle1. Later fixture corrections explicitly assign queued background priority and wait for the main ticket before releasing occupied capacity. The comparable baseline above reruns original production with those same corrected fixtures; the initial 67-to-candidate difference cannot be attributed solely to production repairs.', '', '| Requested category | Original strict pass | Candidate strict pass | Cases each |', '| --- | ---: | ---: | ---: |']
    for category, counts in old['by_category'].items():
        rows.append(f"| {category} | {counts['strict_pass']} | {new['by_category'][category]['strict_pass']} | {counts['cases']} |")
    rows += ['', 'Candidate nonpasses: ' + ', '.join(new['failing_case_ids']) + '.', '', 'Frozen short-deadline queue/retry expectations and blocked-versus-partially-completed status expectations remain visible. A correct source rejection with no artifact write does not turn a mismatched frozen status oracle into a pass. The supplemental controls are a separate denominator.', '', '## Reproduced repairs', '', 'Independent exposed controls reproduced fresh health combined with stale remote capacity, and a larger historical context proof overriding a smaller configured allocation. The scheduler now requires a finite nonboolean resource timestamp aged zero to thirty seconds for remote admission, while preserving optional unknown local CPU resources. Known configured and reported bounds constrain verified context at selection, compatible FIFO ordering, predispatch and returned-result admission. The original probe also retains its configured/reported allocation gate. No model size, server alias or stored historical proof becomes current capacity.', '', 'Registry and transport repairs are owned and documented by the other engineering worker. Source digests below bind this scheduling evidence to its actual imported dependencies, rather than claiming that only the scheduler changed.', '', '| Candidate dependency | SHA-256 |', '| --- | --- |']
    for key, values in new['source_hashes'].items():
        rows.append(f'| {key} | ' + ', '.join(('`' + v + '`' for v in values)) + ' |')
    rows += ['', '## Evidence scope', '', f"Candidate evidence retains {new['controlled_provider_http_posts']} controlled HTTP POSTs ({new['harness_error_http_posts']} from harness-error diagnostics), durable job events and actual overlap up to {new['maximum_observed_controlled_http_overlap']}. Observed scheduler/provider cleanup leaks: {new['observed_cleanup_leaks']} in complete receipts and {new['harness_error_observed_cleanup_leaks']} in harness-error diagnostics. Harness errors without cleanup diagnostics: {new['harness_errors_without_cleanup_diagnostics']}. These are protocol and authority checks, not inference-performance measurements.", '', 'The six workflow verification controls contain one expected positive completion and five negative analysis/transport cases. Original source readbacks, numerical evidence verification and actual isolated artifact write entries determine acceptance; model agreement never verifies a result. Completed protocol deliveries remain distinct from original VERIFIED workflow jobs.', '', 'Production/corpus modifications were prohibited during final runs; per-case dependency snapshots and original raw provider request/response traces are retained. Harness errors preserve dispatch and cleanup diagnostics. All provider sockets, scheduler threads and databases belong to disposable test roots. Owner stores, settings, model services and remote processes are unchanged.', '', '## Live serving and context limits', '', 'The manager found Tailscale port 22 reachable on the active nodes, but fresh Tailscale authentication prevented protected hardware/model discovery. There are no authenticated current GPU/resource identities, healthy compute workers or actual generation responses. Historical context records and model labels do not establish current runtime capacity. Live 8K/16K/32K/64K/128K stages, model throughput and hardware quality remain blocked and unmeasured.', '', 'If existing workers become eligible, the manager can use original verify_context on those existing allocations: refresh exact health/runtime identity and measured resources, preserve privacy and free-slot admission, reserve output tokens inside the total allocation, submit bounded synthetic records with independently held retrieval targets, retain actual prompt usage plus exact retrieval, and record only a successful original proof. Progress to the next stage only after supported proof; never restart, grow allocations, edit deployment or change drivers to create a result. Stop at the first unavailable, failed, busy, resource or payload boundary.', '', 'The original startup growth threshold is expressed in prior prompt-token proof, while verify_context reserves output within the allocation. Therefore a literal prompt target equal to an 8K allocation cannot pass with positive output reserve and cannot satisfy the next 16K growth threshold through that allocation. The independent exposed progression finding remains separate from live testing; configured capacity must not be reported as near-limit retrieval proof. The 262,144-byte request ceiling and maximum existing allocation also remain intact.', '', 'No default model replacement, remote launch or capacity increase follows from these controlled results.']
    output.write_text('\n'.join(rows) + '\n', encoding='utf8', newline='\n')
    results = {'baseline': old, 'candidate': new, 'supplement': extra}
    output.with_name('scheduling_results.json').write_text(json.dumps(results, indent=2) + '\n', encoding='utf8', newline='\n')
    return results
if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('--baseline', type=Path, required=True)
    parser.add_argument('--candidate', type=Path, required=True)
    parser.add_argument('--supplement', type=Path, required=True)
    parser.add_argument('--output', type=Path, default=Path('docs/campaign6/SCHEDULING_REVIEW.md'))
    args = parser.parse_args()
    print(json.dumps(publish(args.baseline, args.candidate, args.supplement, args.output), indent=2))
